  await page.goto(B + 'catalog.html');
  console.log('menu hidden', !(await page.isVisible('#primary-menu')));
  await page.click('.nav-toggle'); console.log('menu shown', await page.isVisible('#primary-menu'));
  await audit('mobile-catalog-menu');
  await page.screenshot({ path: '/tmp/pw/mobile-catalog.png' });
  const overflow = [];
  for (const p of ['index.html','catalog.html','register.html','profile.html']) {
